const LOGO = '<svg viewBox="-170 -170 340 340"><circle r="160" fill="#fff"/><polygon points="0,-120 104,60 -104,60" fill="#0f1f3d"/><polygon points="0,120 104,-60 -104,-60" fill="#e8622c" fill-opacity=".85"/></svg>';
const LC = { in: '#0f1f3d', out: '#e8622c', eng: '#1f9d6b' }, LM = { in: '▲', out: '▼', eng: '◎' };
const today = () => new Date().toLocaleDateString('sv'), uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
let S, ROOT, OPT = {}, V = { tab: 'in', sec: 'prof', full: false };
function loadS() { try { const j = JSON.parse(localStorage.getItem(KEY)); if (j && j.cos) return j; } catch (e) { } return { cos: {}, cur: '' }; }
function saveS() { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (e) { alert('保存に失敗しました：' + e.message); } }
const blank = name => ({ id: uid(), name: name || '', prof: { ind: 'all', target: 'young', fn: {} }, ans: {}, cul: {}, memo: '', updated: today() });
const cur = () => S.cos[S.cur];
const SECS = () => [{ k: 'prof', l: '会社プロフィール', ph: '最初に', m: '◇' }].concat(
  SD.order.map(k => { const a = SD.axes.find(x => x.k === k); return { k, l: a.l, ph: a.layer === 'in' ? '商談の場で聞く（▲中身）' : a.layer === 'out' ? '事前に見て採点（▼見え方）' : '事前＋商談（◎動かし方）', m: LM[a.layer], ax: a }; }),
  [{ k: 'cul', l: '社風カラー', ph: '商談の最後に', m: '◆' }]);

function demo() { const c = blank('サンプル建設株式会社（架空）'); c.prof = Object.assign(c.prof, SD.demo.prof); c.ans = Object.assign({}, SD.demo.ans); c.cul = Object.assign({}, SD.demo.cul); c.memo = '【デモ】社長「若い子が続かない。求人は媒体の担当者に任せている」'; return c; }

function mount(el, opt) {
  ROOT = el; OPT = opt || {}; S = loadS();
  if (!document.getElementById('sx-css')) { const st = document.createElement('style'); st.id = 'sx-css'; st.textContent = CSS; document.head.appendChild(st); }
  if (OPT.pick) { const hit = Object.values(S.cos).find(c => c.name === OPT.pick); if (hit) S.cur = hit.id; else { const c = blank(OPT.pick); if (OPT.prof) Object.assign(c.prof, OPT.prof); S.cos[c.id] = c; S.cur = c.id; saveS(); } }
  if (!cur()) { const ids = Object.keys(S.cos); if (ids.length) S.cur = ids[0]; else { const c = demo(); S.cos[c.id] = c; S.cur = c.id; saveS(); } }
  if (!el._sx && /^#(res|doc|in)$/.test(location.hash)) V.tab = location.hash.slice(1);
  el.classList.add('sx');
  if (!el._sx) { el._sx = 1; el.addEventListener('click', onClick); el.addEventListener('change', onChange); }
  render();
}
function render() {
  const co = cur(), R = calc(co), keep = window.scrollY;
  ROOT.innerHTML = `<div class="sx-top"><div class="sx-logo">${LOGO}<div>採用スター診断<small>中身 × 見え方 × 動かし方で、採用力を見える化</small></div></div>
 <select data-c="pick">${Object.values(S.cos).sort((a, b) => a.name.localeCompare(b.name, 'ja')).map(c => `<option value="${c.id}" ${c.id === S.cur ? 'selected' : ''}>${esc(c.name || '（名称未入力）')}</option>`).join('')}</select>
 <button class="sx-b g" data-a="new">＋ 新しい会社</button><span class="sx-sp"></span>
 <button class="sx-b g" data-a="full">🖥 全画面</button><button class="sx-b p" data-a="print">🖨 診断レポート</button><span style="position:relative"><button class="sx-b g" data-a="menu" aria-label="その他の操作">⋯</button>${V.menu ? `<div class="sx-pop">${[['m1', '📄 この診断を複製する（再診断用）'], ['m5', '🧪 サンプル会社を追加'], ['m3', '💾 全データを書き出す（バックアップ）'], ['m4', '📂 バックアップを読み込む'], ['m2', '🗑 この会社の診断を削除']].map(m => `<button data-a="${m[0]}">${m[1]}</button>`).join('')}</div>` : ''}</span></div>
 <div class="sx-tabs">${[['in', '① 入力'], ['res', '② 診断結果'], ['doc', '③ 使い方と根拠']].map(t => `<button class="sx-tab ${V.tab === t[0] ? 'on' : ''}" data-a="tab" data-v="${t[0]}">${t[1]}</button>`).join('')}<span class="sx-sp"></span><span class="sx-mut" style="align-self:center">入力 ${R.answered + R.unknown}/${R.total}（${R.done}%）${co.updated ? '｜更新 ' + co.updated : ''}</span></div>
 ${V.tab === 'in' ? vInput(co, R) : V.tab === 'res' ? vResult(co, R) : vDoc()}`;
  window.scrollTo(0, keep);
}

/* ---------- 入力 ---------- */
function secProg(sec, co) { if (sec.ax) { const n = sec.ax.items.filter(it => co.ans[it.k] != null && co.ans[it.k] !== '').length; return [n, sec.ax.items.length]; } if (sec.k === 'cul') return [SD.culture.filter(c => co.cul[c.k]).length, SD.culture.length]; return [['ind', 'size', 'target'].filter(k => co.prof[k]).length + (co.name ? 1 : 0), 4]; }
